                    /**
                    * Predict readable class name
                    */
                    const char* predictLabel(float *x) {
                        return idxToLabel(predict(x));
                    }

                    /**
                    * Convert class idx to readable name
                    */
                    const char* idxToLabel(uint8_t classIdx) {
                        switch (classIdx) {
                            case 0:
                            return "lying";
                            case 1:
                            return "running";
                            case 2:
                            return "sitting";
                            case 3:
                            return "standing";
                            case 4:
                            return "trembling";
                            case 5:
                            return "walking";
                            default:
                            return "Houston we have a problem";
                        }
                    }

